(3846324, 544127, 70181, '<td valign="top">Beautiful colors, very sharp.  Nice job.</td>', 'Beautiful colors, very sharp.  Nice job.', '2007-06-28 20:50:55.000000', NULL, 1),
(3846328, 543869, 70181, '<td valign="top">Nice composition.  Great use of the color against the colorless background.  The only flaw is the distracting bit of yellow on the left side.</td>', 'Nice composition.  Great use of the color against the colorless background.  The only flaw is the distracting bit of yellow on the left side.', '2007-06-28 20:52:18.000000', NULL, 1),
(3846329, 544032, 70181, '<td valign="top">Beautiful shot.  Nice dramatic clouds.  Good composition.  Great job on the blue and green, but the red comes across as a little overdone.  Although that may be my monitor.</td>', 'Beautiful shot.  Nice dramatic clouds.  Good composition.  Great job on the blue and green, but the red comes across as a little overdone.  Although that may be my monitor.', '2007-06-28 20:52:22.000000', NULL, 1),
(3846330, 543909, 70181, '<td valign="top">Very sharp.  Nice dramatic sky.  Great job.</td>', 'Very sharp.  Nice dramatic sky.  Great job.', '2007-06-28 20:52:24.000000', NULL, 1),
(3846331, 543918, 70181, '<td valign="top">Beautiful shot.  Excellent detail.  You shot it at a nice time of day.  Just dark enough to need the lights, but light enough to get some blue in the sky.</td>', 'Beautiful shot.  Excellent detail.  You shot it at a nice time of day.  Just dark enough to need the lights, but light enough to get some blue in the sky.', '2007-06-28 20:52:26.000000', NULL, 1),
