(3846334, 544096, 70181, '<td valign="top">Cool looking frog.  It really stands out against the rest of the photo.</td>', 'Cool looking frog.  It really stands out against the rest of the photo.', '2007-06-28 20:53:26.000000', NULL, 1),
(3846335, 542196, 70181, '<td valign="top">Nice detail.  I like it against the white.  The flowers really jump out at the viewer.</td>', 'Nice detail.  I like it against the white.  The flowers really jump out at the viewer.', '2007-06-28 20:53:30.000000', NULL, 1),
