(3847735, 543433, 73452, '<td valign="top">Flowers?!  no way!  just kidding.  Kinda looks noisy to me. yep.</td>', 'Flowers?!  no way!  just kidding.  Kinda looks noisy to me. yep.', '2007-06-29 03:34:21.000000', NULL, 1),
(3847739, 543700, 73452, '<td valign="top">Though there is plenty of color, the challenge description says "that offsets your subject from the rest of the photo"  not to poke at you or anything, i was just saying that it dosent really offset itself from the rest of the pohot.  ok, now im just rambling on and on.  lets start over shall we?INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3848698, 543518, 42100, '<td valign="top">Very mysterious looking macro with the DOF and the unique plant.  Nice color tones...very nice photo!</td>', 'Very mysterious looking macro with the DOF and the unique plant.  Nice color tones...very nice photo!', '2007-06-29 12:58:50.000000', NULL, 1),
(3848706, 542079, 48471, '<td valign="top">I guess the title is too ambitious, but, anyway, a good refreshing photo of colourfull houses, instead of flowers.</td>', 'I guess the title is too ambitious, but, anyway, a good refreshing photo of colourfull houses, instead of flowers.', '2007-06-29 12:59:58.000000', NULL, 1),
(3848762, 544199, 42100, '<td valign="top">Soft and delicate...and the shallow DOF really adds to that vibe of the photo.  Although a more gradual transition of focus might be nicer.  The lighting adds very nicely to the mood of the photo.  Well done!</td>', 'Soft and delicate...and the shallow DOF really adds to that vibe of the photo.  Although a more gradual transition of focus might be nicer.  The lighting adds very nicely to the mood of the photo.  Well done!', '2007-06-29 13:26:34.000000', NULL, 1),
(3848768, 540919, 42100, '<td valign="top">Very nice silhouette of the solitary figure.  Without the cowboy hat he could quite easily disappear into this scene.  Beautiful sky and photo!</td>', 'Very nice silhouette of the solitary figure.  Without the cowboy hat he could quite easily disappear into this scene.  Beautiful sky and photo!', '2007-06-29 13:28:54.000000', NULL, 1),
(3848805, 542265, 80598, '<td valign="top">I liked the photo. Just not for this theme</td>', 'I liked the photo. Just not for this theme', '2007-06-29 13:46:51.000000', NULL, 1),
(3848815, 543739, 80598, '<td valign="top">Great title! it really adds emotion to the image</td>', 'Great title! it really adds emotion to the image', '2007-06-29 13:52:35.000000', NULL, 1),
(3848846, 542511, 80598, '<td valign="top">beautiful!</td>', 'beautiful!', '2007-06-29 14:06:19.000000', NULL, 1),
(3848858, 541780, 80598, '<td valign="top">great picture! nice lines</td>', 'great picture! nice lines', '2007-06-29 14:12:41.000000', NULL, 1),
(3848867, 543909, 42100, '<td valign="top">I really like the deep rich dark tones, they really seem to just right for this photo.  You really made that old work truck look cool...great photo!</td>', 'I really like the deep rich dark tones, they really seem to just right for this photo.  You really made that old work truck look cool...great photo!', '2007-06-29 14:16:10.000000', NULL, 1),
(3848868, 543869, 80598, '<td valign="top">interesting visual. I''m not sure if I like the many textures, but it is interesting.</td>', 'interesting visual. I''m not sure if I like the many textures, but it is interesting.', '2007-06-29 14:17:14.000000', NULL, 1),
(3848871, 542413, 42100, '<td valign="top">Good use of shallow DOF in this photo...you got the angles/POV just right for it.  Everything fades nicely towards the background.  Great color and clarity as  well.  Excellent!</td>', 'Good use of shallow DOF in this photo...you got the angles/POV just right for it.  Everything fades nicely towards the background.  Great color and clarity as  well.  Excellent!', '2007-06-29 14:17:53.000000', NULL, 1),
(3848875, 543109, 80598, '<td valign="top">wow! the water drops makes the flower seem like it is crying. I love it!</td>', 'wow! the water drops makes the flower seem like it is crying. I love it!', '2007-06-29 14:18:35.000000', NULL, 1),
(3848879, 542868, 42100, '<td valign="top">Very good color and clarity.  This reminds me of the NBC peacock.  Nicely done!</td>', 'Very good color and clarity.  This reminds me of the NBC peacock.  Nicely done!', '2007-06-29 14:18:55.000000', NULL, 1),
(3848886, 543869, 42100, '<td valign="top">Unlike objects...but the blend together very nicely for a very good photo!</td>', 'Unlike objects...but the blend together very nicely for a very good photo!', '2007-06-29 14:20:48.000000', NULL, 1),
(3848891, 544087, 42100, '<td valign="top">Very nice candid...catching her daydreaming like that makes for a nice photographic moment.  Everything is so crisp and colorful.  Well done!</td>', 'Very nice candid...catching her daydreaming like that makes for a nice photographic moment.  Everything is so crisp and colorful.  Well done!', '2007-06-29 14:22:38.000000', NULL, 1),
(3848899, 542453, 42100, '<td valign="top">Great color and crispness to this macro...interesting subject as well.  Very nice photo!</td>', 'Great color and crispness to this macro...interesting subject as well.  Very nice photo!', '2007-06-29 14:24:13.000000', NULL, 1),
(3848940, 540866, 42100, '<td valign="top">Very pretty...a little bit Monet-ish, I think.  Love the colors and tones. Great job!</td>', 'Very pretty...a little bit Monet-ish, I think.  Love the colors and tones. Great job!', '2007-06-29 14:39:08.000000', NULL, 1),
(3848949, 543341, 42100, '<td valign="top">Very cool abstract-ish photograph of water and refractions.  This is an extremely beautiful photograph...like a sedative for the nerves!</td>', 'Very cool abstract-ish photograph of water and refractions.  This is an extremely beautiful photograph...like a sedative for the nerves!', '2007-06-29 14:41:02.000000', NULL, 1),
(3848975, 543173, 42100, '<td valign="top">Contrast is very harsh, to help control contrast try photographing in shade or during the hours after the sun rises or before the sun sets.  Fill lighting can help also but there is a number of methods and takes some learning.</td>', 'Contrast is very harsh, to help control contrast try photographing in shade or during the hours after the sun rises or before the sun sets.  Fill lighting can help also but there is a number of methods and takes some learning.', '2007-06-29 14:46:15.000000', NULL, 1),
(3848998, 541371, 42100, '<td valign="top">Subject matter is way too busy for the eye to find interest.  Finding a strong and defining texture or pattern could make this much more dynamic.</td>', 'Subject matter is way too busy for the eye to find interest.  Finding a strong and defining texture or pattern could make this much more dynamic.', '2007-06-29 14:52:07.000000', NULL, 1),
(3848999, 542750, 42100, '<td valign="top">Some fill-flash can really help control shadows in bright sunlight, takes a little practice to get right though.</td>', 'Some fill-flash can really help control shadows in bright sunlight, takes a little practice to get right though.', '2007-06-29 14:52:09.000000', NULL, 1),
(3849140, 543909, 60805, '<td valign="top">ahhh must be an icelander. The steep gradient really reigns in the theme "burst of colour" with that contrast. 10</td>', 'ahhh must be an icelander. The steep gradient really reigns in the theme "burst of colour" with that contrast. 10', '2007-06-29 15:56:24.000000', NULL, 1),
(3849158, 543109, 60805, '<td valign="top">perfect burst to me :)   9</td>', 'perfect burst to me :)   9', '2007-06-29 16:05:21.000000', NULL, 1),
(3849168, 542066, 79904, '<td valign="top">I love this shot!  Very nice colors.</td>', 'I love this shot!  Very nice colors.', '2007-06-29 16:08:30.000000', NULL, 1),
(3849205, 542088, 60805, '<td valign="top">I dont get burst of colour from this. But it really is a nice capture. Also! from a technical point of view u might consider some sharpening, the image comes off kind of soft. It also looks like a midday shot, u might want to try shooting dusk or dawn or overcast to rid of the harsh shadows. Subject also seems too centered. Anyway enough of my ranting, my suggestions are IMHO of course so u may choose to ignore them if u want :)</td>', 'I dont get burst of colour from this. But it really is a nice capture. Also! from a technical point of view u might consider some sharpening, the image comes off kind of soft. It also looks like a midday shot, u might want to try shooting dusk or dawn or overcast to rid of the harsh shadows. Subject also seems too centered. Anyway enough of my ranting, my suggestions are IMHO of course so u may choose to ignore them if u want :)', '2007-06-29 16:24:35.000000', NULL, 1),
(3849236, 544032, 60805, '<td valign="top">iceland</td>', 'iceland', '2007-06-29 16:36:09.000000', NULL, 1),
