INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3862624, 544090, 60581, '<td valign="top">Sorry I did not understand the photograph, it looks like a car but because of some effects I lost the track.</td>', 'Sorry I did not understand the photograph, it looks like a car but because of some effects I lost the track.', '2007-07-03 11:20:32.000000', NULL, 1),
(3862627, 544262, 60581, '<td valign="top">I think this needs little bit of PP, otherwise nice shot!!!</td>', 'I think this needs little bit of PP, otherwise nice shot!!!', '2007-07-03 11:23:02.000000', NULL, 1),
(3862745, 542746, 42100, '<td valign="top">The bright splashes of color really look great and the portrait of an artist theme comes across well.  Only nitpick is the the eyes...upside down and with the funny head angle they really look funky.</td>', 'The bright splashes of color really look great and the portrait of an artist theme comes across well.  Only nitpick is the the eyes...upside down and with the funny head angle they really look funky.', '2007-07-03 12:08:18.000000', NULL, 1),
(3862768, 543251, 69368, '<td valign="top">very good lighting, great powerful colors, nice composition. good luck!</td>', 'very good lighting, great powerful colors, nice composition. good luck!', '2007-07-03 12:15:49.000000', NULL, 1),
(3862773, 541862, 80819, '<td valign="top">WOW - I reaslly like this picture</td>', 'WOW - I reaslly like this picture', '2007-07-03 12:16:40.000000', NULL, 1),
(3862775, 544199, 53571, '<td valign="top">Love the depth of field.</td>', 'Love the depth of field.', '2007-07-03 12:17:25.000000', NULL, 1),
(3862777, 542732, 53571, '<td valign="top">Feels like a snapshot to me.</td>', 'Feels like a snapshot to me.', '2007-07-03 12:17:36.000000', NULL, 1),
(3862779, 544258, 42100, '<td valign="top">Nice bright color and very good lighting.  Well done!</td>', 'Nice bright color and very good lighting.  Well done!', '2007-07-03 12:18:20.000000', NULL, 1),
(3862780, 543873, 53571, '<td valign="top">Love it.... needs to be larger for full effect.</td>', 'Love it.... needs to be larger for full effect.', '2007-07-03 12:18:42.000000', NULL, 1),
(3862783, 544223, 53571, '<td valign="top">Nice sunset.</td>', 'Nice sunset.', '2007-07-03 12:18:55.000000', NULL, 1),
(3862791, 543519, 42100, '<td valign="top">Very nice color...has a softness about it and an intensity at the same time.  Very nice composition as well.  Well done!</td>', 'Very nice color...has a softness about it and an intensity at the same time.  Very nice composition as well.  Well done!', '2007-07-03 12:20:32.000000', NULL, 1),
(3862797, 541819, 53571, '<td valign="top">Not sure it fits the challenge.</td>', 'Not sure it fits the challenge.', '2007-07-03 12:21:25.000000', NULL, 1),
(3862798, 542224, 42100, '<td valign="top">Fascinating light in this photograph...the blue of the boat really glows.  Nicely done!</td>', 'Fascinating light in this photograph...the blue of the boat really glows.  Nicely done!', '2007-07-03 12:21:33.000000', NULL, 1),
(3862800, 543588, 53571, '<td valign="top">Color is nice. I would like to see this closer.</td>', 'Color is nice. I would like to see this closer.', '2007-07-03 12:21:59.000000', NULL, 1),
(3862808, 543907, 42100, '<td valign="top">The dark and somber tones really go well with the fact the butterfly is dead.  It''s very interesting how the little specks of color in the soil echo the colors in the butterfly''s wings.  Nicely done!</td>', 'The dark and somber tones really go well with the fact the butterfly is dead.  It''s very interesting how the little specks of color in the soil echo the colors in the butterfly''s wings.  Nicely done!', '2007-07-03 12:24:16.000000', NULL, 1),
(3862820, 543735, 42100, '<td valign="top">Very striking and dynamic composition...great foreground, great background and the skiff just pops right out.  This would look so much better larger...how much must we beg for at least 720 px!?!</td>', 'Very striking and dynamic composition...great foreground, great background and the skiff just pops right out.  This would look so much better larger...how much must we beg for at least 720 px!?!', '2007-07-03 12:27:14.000000', NULL, 1),
(3862837, 544050, 42100, '<td valign="top">The silhouette of that structure and tree look great against that amber sky.  The silhouette even has some nice highlight details.  Very dynamic and beautiful photo!</td>', 'The silhouette of that structure and tree look great against that amber sky.  The silhouette even has some nice highlight details.  Very dynamic and beautiful photo!', '2007-07-03 12:32:14.000000', NULL, 1),
(3862883, 544203, 42100, '<td valign="top">Sea kayaking looks like it would be a blast, especially around icebergs.  Ice always has such beautiful blues...very nice photo!</td>', 'Sea kayaking looks like it would be a blast, especially around icebergs.  Ice always has such beautiful blues...very nice photo!', '2007-07-03 12:44:51.000000', NULL, 1),
(3862944, 543019, 42100, '<td valign="top">The bright colors are great...this photo is a bit like kaleidoscope with all the bits of color.  The headless composition(with the exceptions of the shadows) creates a very intriguing tension.  Real good stuff here...nice!</td>', 'The bright colors are great...this photo is a bit like kaleidoscope with all the bits of color.  The headless composition(with the exceptions of the shadows) creates a very intriguing tension.  Real good stuff here...nice!', '2007-07-03 13:03:41.000000', NULL, 1),
(3862948, 543841, 42100, '<td valign="top">Very nice light...the flower and stem are illuminated nicely, while the surroundings are much darker.  Really allows the subject to pop quite nicely.  Well done!</td>', 'Very nice light...the flower and stem are illuminated nicely, while the surroundings are much darker.  Really allows the subject to pop quite nicely.  Well done!', '2007-07-03 13:05:22.000000', NULL, 1),
